-- =====================================================================
-- V7_10 — Persona inbox pages.
--   - pico:manager-inbox       — Manager approval queue (Workflow + actions)
--   - pico:operator-dashboard  — Shop-floor live metrics + queue
-- =====================================================================

INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:manager-inbox','Manager Inbox','Pending approvals across all dispatch workflows.','Persona','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:manager-inbox');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"schemaVersion":2,"layout":{"type":"Section","props":{"title":"Pending Manager Approvals"},"children":[{"type":"WorkflowQueueList","props":{"persona":"Manager","pageSize":25,"cardFields":["business_ref","current_state","workflow_code","updated_at"]}}]}}', 'V7_10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:manager-inbox' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

INSERT INTO page_definition (tenant_id, code, title, description, category, status) SELECT 1,'pico:operator-dashboard','Operator Dashboard','Shop-floor — open gate-passes + live KPIs.','Dashboard','PUBLISHED' WHERE NOT EXISTS (SELECT 1 FROM page_definition WHERE tenant_id=1 AND code='pico:operator-dashboard');

INSERT INTO page_version (page_id, version, status, body_json, rationale, published_at) SELECT p.id, 1, 'PUBLISHED', '{"schemaVersion":2,"layout":{"type":"Grid","props":{"gap":16,"style":{"padding":16}},"children":[{"type":"KPI","props":{"label":"Open Gate Passes","intervalMs":15000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"nin","value":["CLOSED","QC_REJECTED","DRAFT"]}]}}}},{"type":"KPI","props":{"label":"Awaiting QC","intervalMs":15000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"eq","value":"DISPATCH_QUEUED"}]}}}},{"type":"KPI","props":{"label":"Awaiting Weighment","intervalMs":15000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"eq","value":"QC_APPROVED"}]}}}},{"type":"KPI","props":{"label":"Unloading","intervalMs":15000,"dataSource":{"type":"entity","entity":"GatePass","filter":{"and":[{"field":"tenant_id","op":"eq","value":"ctx:tenantId"},{"field":"status","op":"eq","value":"WEIGHMENT_LOADED"}]}}}}]}}', 'V7_10', CURRENT_TIMESTAMP FROM page_definition p WHERE p.tenant_id=1 AND p.code='pico:operator-dashboard' AND NOT EXISTS (SELECT 1 FROM page_version v WHERE v.page_id = p.id AND v.version = 1);

UPDATE page_definition SET current_version_id = (SELECT id FROM page_version WHERE page_id = page_definition.id AND version = 1 LIMIT 1) WHERE tenant_id=1 AND code IN ('pico:manager-inbox','pico:operator-dashboard') AND current_version_id IS NULL;
